<?php /** @var list<array<string,mixed>> $rows */ /** @var int $total */ /** @var int $page */ /** @var int $perPage */ /** @var array<string,mixed> $filters */ /** @var array<string,mixed> $qs */ /** @var array<string,int> $dash */ /** @var bool $canCreate */ /** @var bool $profileOk */
$sel = static fn (string $a, string $b): string => $a === $b ? ' selected' : ''; $labels = ['draft' => 'Draft', 'issued' => 'Issued', 'partially_paid' => 'Partially paid', 'paid' => 'Paid', 'void' => 'Void']; ?>
<div class="page-head"><div><p class="eyebrow">Billing</p><h1>Invoices</h1></div><div class="actions"><?php if ($canCreate) : ?><a class="btn btn-primary" href="/invoices/new">New invoice</a><?php endif; ?><a class="btn btn-ghost" href="/client-payments">Client payments</a></div></div>
<?php if (!$profileOk) : ?><div class="alert alert-error" role="status"><p><strong>Business details are not set.</strong> Invoices cannot be issued until they are (Administration → Business details).</p></div><?php endif; ?>
<div class="stat-grid"><div class="stat"><span class="stat-n"><?= e(money($dash['outstanding_minor'])) ?></span><span class="stat-l">Outstanding</span></div><a class="stat" href="/invoices?overdue=1"><span class="stat-n"><?= (int) $dash['overdue'] ?></span><span class="stat-l">Overdue</span></a>
    <a class="stat" href="/invoices?status=draft"><span class="stat-n"><?= (int) $dash['drafts'] ?></span><span class="stat-l">Drafts</span></a><a class="stat" href="/client-payments?status=pending_verification"><span class="stat-n"><?= (int) $dash['to_verify'] ?></span><span class="stat-l">Payments to verify</span></a></div>
<form method="get" action="/invoices" class="toolbar" role="search"><div class="field"><label for="q">Search</label><input id="q" name="q" type="search" maxlength="100" value="<?= e($filters['q']) ?>"></div>
    <div class="field"><label for="s">Status</label><select id="s" name="status"><option value="">All</option><?php foreach ($labels as $c => $l) : ?><option value="<?= e($c) ?>"<?= $sel($filters['status'], $c) ?>><?= e($l) ?></option><?php endforeach; ?></select></div>
    <div class="field"><label for="from">Issued from</label><input id="from" name="from" type="date" value="<?= e($filters['from']) ?>"></div><div class="field"><label for="to">to</label><input id="to" name="to" type="date" value="<?= e($filters['to']) ?>"></div>
    <div class="field"><label class="check"><input type="checkbox" name="overdue" value="1"<?= $filters['overdue'] ? ' checked' : '' ?>> Overdue only</label></div><div class="field"><button class="btn btn-ghost" type="submit">Filter</button></div></form>
<div class="table-wrap"><table class="table"><thead><tr><th>Invoice</th><th>Client</th><th class="num">Total</th><th class="num">Paid</th><th>Due</th><th>Status</th></tr></thead><tbody>
    <?php foreach ($rows as $r) : ?><tr><td><a href="/invoices/<?= e($r['public_id']) ?>"><strong><?= e($r['reference'] ?? 'Draft') ?></strong></a><br><span class="muted"><?= e($r['title']) ?></span></td><td><?= e($r['client_name']) ?></td><td class="num"><?= e(money($r['total_minor'])) ?></td><td class="num"><?= e(money($r['paid_minor'])) ?></td>
        <td><?= $r['due_date'] ? e(local_date($r['due_date'])) : '—' ?></td><td><span class="badge badge-bi-<?= e($r['status']) ?>"><?= e($labels[$r['status']] ?? $r['status']) ?></span></td></tr><?php endforeach; ?>
    <?php if ($rows === []) : ?><tr><td colspan="6" class="muted">No invoices.</td></tr><?php endif; ?></tbody></table></div>
<?= \Vertex\Core\View::partial('pagination', ['page' => $page, 'perPage' => $perPage, 'total' => $total, 'filters' => $qs]) ?>
